foreach ($wf in @('ci.yml', 'driver-android-signed-hosted.yml', 'chat-data-command.yml', 'android-oneoff-selfhosted.yml', 'flipshot-selfhosted.yml')) {
  Write-Output "=== drivetrack/$wf ==="
  $b64 = gh api "repos/newsdayads/drivetrack/contents/.github/workflows/$wf" --jq '.content'
  $txt = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64))
  $txt -split "`n" | Select-String -Pattern "runs-on|retention-days|upload-artifact|schedule|cron|concurrency"
}

foreach ($wf in @('hourly-publisher.yml', 'news-api-test.yml', 'offline-news-reader.yml')) {
  Write-Output "=== tigeriq-media-content/$wf ==="
  $b64 = gh api "repos/newsdayads/tigeriq-media-content/contents/.github/workflows/$wf" --jq '.content'
  $txt = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64))
  $txt -split "`n" | Select-String -Pattern "runs-on|retention-days|upload-artifact|schedule|cron|concurrency"
}

$wt = "$env:TEMP\wt-ci-hygiene-2"
if (Test-Path $wt) { git worktree remove --force $wt }
git worktree add -b chore/ci-retention-3d-all $wt origin/main
Get-ChildItem "$wt\.github\workflows\*.yml" | ForEach-Object {
  $txt = Get-Content $_.FullName -Raw
  $new = $txt -replace 'retention-days:\s*(7|14|30)\b', 'retention-days: 3'
  if ($_.Name -eq 'revenue-audit-portable.yml' -and ($new -notmatch '(?m)^concurrency:')) {
    $new = $new -replace '(?m)^(permissions:\r?\n)', "concurrency:`n  group: revenue-audit-portable-`${{ github.ref }}`n  cancel-in-progress: true`n`n`$1"
  }
  if ($new -ne $txt) {
    [System.IO.File]::WriteAllText($_.FullName, $new, (New-Object System.Text.UTF8Encoding($false)))
    Write-Output "Updated $($_.Name)"
  }
}
